type CardObservation struct {
	// The brand of the card.
	Brand *string `json:"brand,omitempty"`

	// The reason why the card was canceled.
	CancellationReason *string `json:"cancellationReason,omitempty"`

	Cardholder *JSON `json:"cardholder,omitempty"`

	// Time at which the object was created. Measured in seconds since the Unix epoch.
	Created *int64 `json:"created,omitempty"`

	// Three-letter [ISO currency code](https://www.iso.org/iso-4217-currency-codes.html), in lowercase. Supported currencies are `usd` in the US, `eur` in the EU, and `gbp` in the UK.
	Currency *string `json:"currency,omitempty"`

	// The expiration month of the card.
	ExpMonth *int64 `json:"expMonth,omitempty"`

	// The expiration year of the card.
	ExpYear *int64 `json:"expYear,omitempty"`

	// The financial account this card is attached to.
	FinancialAccount *string `json:"financialAccount,omitempty"`

	// Unique identifier for the object.
	ID *string `json:"id,omitempty"`

	// The last 4 digits of the card number.
	Last4 *string `json:"last4,omitempty"`

	// Stripe’s assessment of whether this card’s details have been compromised. If this property isn't null, cancel and reissue the card to prevent fraudulent activity risk.
	LatestFraudWarning *JSON `json:"latestFraudWarning,omitempty"`

	// Rules that control the lifecycle of this card, such as automatic cancellation. Refer to our [documentation](/issuing/controls/lifecycle-controls) for more details.
	LifecycleControls *JSON `json:"lifecycleControls,omitempty"`

	// If the object exists in live mode, the value is `true`. If the object exists in test mode, the value is `false`.
	Livemode *bool `json:"livemode,omitempty"`

	// Set of [key-value pairs](https://docs.stripe.com/api/metadata) that you can attach to an object. This can be useful for storing additional information about the object in a structured format.
	Metadata map[string]string `json:"metadata,omitempty"`

	// String representing the object's type. Objects of the same type share the same value.
	Object *string `json:"object,omitempty"`

	// The personalization design object belonging to this card.
	PersonalizationDesign *string `json:"personalizationDesign,omitempty"`

	// The latest card that replaces this card, if any.
	ReplacedBy *string `json:"replacedBy,omitempty"`

	// The card this card replaces, if any.
	ReplacementFor *string `json:"replacementFor,omitempty"`

	// The reason why the previous card needed to be replaced.
	ReplacementReason *string `json:"replacementReason,omitempty"`

	// Text separate from cardholder name, printed on the card.
	SecondLine *string `json:"secondLine,omitempty"`

	// Where and how the card will be shipped.
	Shipping *JSON `json:"shipping,omitempty"`

	SpendingControls *JSON `json:"spendingControls,omitempty"`

	// Whether authorizations can be approved on this card. May be blocked from activating cards depending on past-due Cardholder requirements. Defaults to `inactive`.
	Status *string `json:"status,omitempty"`

	// The type of the card.
	Type *string `json:"type,omitempty"`

	// Information relating to digital wallets (like Apple Pay and Google Pay).
	Wallets *JSON `json:"wallets,omitempty"`
}

